'use strict';

var discreteUniform = require( '@stdlib/random/base/discrete-uniform' );
var bernoulli = require( '@stdlib/random/base/bernoulli' );
var filledBy = require( '@stdlib/array/base/filled-by' );
var objarray2tidy = require( '@stdlib/plot/vega/data/tidy/from-object-array' );
var splitOnKey = require( './../lib' );

function clbk( i ) {
	return {
		'a': i,
		'b': discreteUniform( -100, 100 ),
		'c': bernoulli( 0.5 )
	};
}

// Generate a "raw" data array:
var arr = filledBy( 20, clbk );

// Convert the raw data to a tidy dataset...
var mapping = {
	'a': 'x',
	'b': 'y',
	'c': 'z'
};
var dataset = objarray2tidy( arr, 'series', mapping );

// Split the tidy data set according to the re-keyed "z" property:
var data = splitOnKey( dataset, 'z' );

// Print the results:
var out = data[ 0 ].toJSON();
console.log( out );

out = data[ 1 ].toJSON();
console.log( out );

console.log( JSON.stringify( data ) );
